## `config.yml` — new options (example)

```yaml
# ... keep all your existing config ...

grouping_summaries:
  enabled: true
  items:
    # STANDARD SUMMARY with % of total + Top-N
    - name: "Paid_By_Country"
      filter:
        queries: ["status == 'PAID'"]
      group_by: ["country"]
      aggregations:
        amount: ["sum"]
        balance: ["sum"]
      sort_by: ["country"]

      # NEW: percent-of-total columns (computed on aggregated column names)
      percent_of_total:
        enabled: true
        by: []                        # [] = overall; or e.g. ["country_region"]
        columns: ["amount_sum", "balance_sum"]
        suffix: "_pct"
        scale: 100                    # 100 => percentage; 1 => proportion
        decimals: 2

      # NEW: Top-N per group (after % columns, before totals)
      topn:
        enabled: true
        by: []                        # group within these keys for ranking; [] = global
        sort_column: "amount_sum"     # must exist in the summary
        n: 5
        ascending: false              # false => largest first
        keep_ties: true               # if equal, keep all tied rows

      totals_row:
        enabled: true
        label: "TOTAL"
        label_column: "country"

    # PIVOT summary with date bucket + margins
    - name: "Pivot_Month_x_Country"
      date_bucket:
        column: "invoice_date"
        freq: "MS"
        label: "month"
        parse_if_needed: true
      filter:
        queries: ["amount > 0"]
      pivot:
        rows: ["month"]
        cols: ["country"]
        values:
          amount: ["sum"]
          balance: ["sum"]
        fill_value: 0
        margins: true
        margins_name: "TOTAL"

      # % of total on pivot (operates on flattened columns like 'amount_sum_IN')
      percent_of_total:
        enabled: true
        by: []                                # e.g., ["month"] to get row-wise totals (% by month)
        columns: []                            # leave empty to auto-detect numeric value columns
        suffix: "_pct"
        scale: 100
        decimals: 2

      # Top-N per group for pivot (after flatten/reset_index)
      topn:
        enabled: false                         # usually off for pivot grids

      totals_row:
        enabled: false                         # usually not needed when margins=true
```

> Note: After aggregation, columns look like `amount_sum`, `balance_sum`, etc. Use those names in `percent_of_total.columns`.

