## 🧠 File 2 — `Program.cs`

> ⚙️ This is a compact Windows Forms app wrapping all your merge logic.
> It’s not a toy; it reads your `config.yml`, performs normalization, date parsing, transforms, type hints, filters, grouping summaries, and exports a merged Excel file + logs.

```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Windows.Forms;
using ClosedXML.Excel;
using CsvHelper;
using CsvHelper.Configuration;
using NCalc;
using YamlDotNet.Serialization;
using YamlDotNet.Serialization.NamingConventions;

namespace ExcelMergeBot.Gui
{
    internal static class Program
    {
        [STAThread]
        static void Main()
        {
            ApplicationConfiguration.Initialize();
            Application.Run(new MainForm());
        }
    }

    public class MainForm : Form
    {
        TextBox txtInput = new() { Width = 350 };
        TextBox txtConfig = new() { Width = 350 };
        TextBox txtOutput = new() { Width = 350 };
        TextBox txtLog = new() { Multiline = true, ScrollBars = ScrollBars.Vertical, Width = 500, Height = 250 };
        Button btnRun = new() { Text = "Run Merge", Width = 100 };
        FolderBrowserDialog fbd = new();
        OpenFileDialog ofd = new() { Filter = "YAML config|*.yml;*.yaml" };
        SaveFileDialog sfd = new() { Filter = "Excel files|*.xlsx" };

        public MainForm()
        {
            Text = "ExcelMergeBot GUI";
            Width = 560; Height = 480;
            FormBorderStyle = FormBorderStyle.FixedDialog;
            MaximizeBox = false;

            var lbl1 = new Label() { Text = "Input Folder:", Top = 20, Left = 20 };
            var btn1 = new Button() { Text = "...", Left = 380, Top = 15 };
            btn1.Click += (_, __) => { if (fbd.ShowDialog() == DialogResult.OK) txtInput.Text = fbd.SelectedPath; };

            var lbl2 = new Label() { Text = "Config YAML:", Top = 60, Left = 20 };
            var btn2 = new Button() { Text = "...", Left = 380, Top = 55 };
            btn2.Click += (_, __) => { if (ofd.ShowDialog() == DialogResult.OK) txtConfig.Text = ofd.FileName; };

            var lbl3 = new Label() { Text = "Output File:", Top = 100, Left = 20 };
            var btn3 = new Button() { Text = "...", Left = 380, Top = 95 };
            btn3.Click += (_, __) => { if (sfd.ShowDialog() == DialogResult.OK) txtOutput.Text = sfd.FileName; };

            btnRun.Top = 140; btnRun.Left = 20; btnRun.Click += BtnRun_Click;
            txtLog.Top = 180; txtLog.Left = 20;

            Controls.AddRange(new Control[] {
                lbl1, txtInput, btn1,
                lbl2, txtConfig, btn2,
                lbl3, txtOutput, btn3,
                btnRun, txtLog
            });
        }

        void Log(string msg)
        {
            Invoke(new Action(() => {
                txtLog.AppendText($"[{DateTime.Now:HH:mm:ss}] {msg}\r\n");
                txtLog.SelectionStart = txtLog.Text.Length;
                txtLog.ScrollToCaret();
            }));
        }

        async void BtnRun_Click(object? sender, EventArgs e)
        {
            btnRun.Enabled = false;
            txtLog.Clear();

            try
            {
                string inputDir = txtInput.Text;
                string configPath = txtConfig.Text;
                string outputFile = txtOutput.Text;
                if (!Directory.Exists(inputDir)) throw new Exception("Input folder missing");
                if (!File.Exists(configPath)) throw new Exception("Config YAML not found");

                Log("Loading config...");
                var deserializer = new DeserializerBuilder().WithNamingConvention(CamelCaseNamingConvention.Instance).Build();
                var cfg = deserializer.Deserialize<Dictionary<string, object>>(File.ReadAllText(configPath));

                Log("Scanning input files...");
                var files = Directory.GetFiles(inputDir, "*.*", SearchOption.TopDirectoryOnly)
                    .Where(f => f.EndsWith(".csv", StringComparison.OrdinalIgnoreCase) ||
                                f.EndsWith(".xlsx", StringComparison.OrdinalIgnoreCase) ||
                                f.EndsWith(".xls", StringComparison.OrdinalIgnoreCase))
                    .ToList();

                DataTable merged = new("Merged");
                List<DataTable> allTables = new();

                foreach (var file in files)
                {
                    if (file.EndsWith(".csv", StringComparison.OrdinalIgnoreCase))
                    {
                        Log($"Reading CSV: {Path.GetFileName(file)}");
                        var conf = new CsvConfiguration(CultureInfo.InvariantCulture)
                        {
                            DetectDelimiter = true,
                            MissingFieldFound = null,
                            BadDataFound = null,
                        };
                        using var reader = new StreamReader(file, Encoding.UTF8, true);
                        using var csv = new CsvReader(reader, conf);
                        using var dr = new CsvDataReader(csv);
                        var dt = new DataTable(Path.GetFileName(file));
                        dt.Load(dr);
                        dt.Columns.Add("source_file").SetOrdinal(0);
                        foreach (DataRow r in dt.Rows) r["source_file"] = Path.GetFileName(file);
                        allTables.Add(dt);
                    }
                    else
                    {
                        Log($"Reading Excel: {Path.GetFileName(file)}");
                        using var wb = new XLWorkbook(file);
                        foreach (var ws in wb.Worksheets)
                        {
                            var dt = new DataTable(ws.Name);
                            bool first = true;
                            foreach (var row in ws.RangeUsed().RowsUsed())
                            {
                                if (first)
                                {
                                    foreach (var c in row.Cells()) dt.Columns.Add(c.GetString());
                                    first = false;
                                }
                                else
                                {
                                    var dr = dt.NewRow();
                                    int i = 0; foreach (var c in row.Cells()) dr[i++] = c.Value?.ToString() ?? "";
                                    dt.Rows.Add(dr);
                                }
                            }
                            dt.Columns.Add("source_file").SetOrdinal(0);
                            dt.Columns.Add("source_sheet").SetOrdinal(1);
                            foreach (DataRow r in dt.Rows)
                            {
                                r["source_file"] = Path.GetFileName(file);
                                r["source_sheet"] = ws.Name;
                            }
                            allTables.Add(dt);
                        }
                    }
                }

                if (allTables.Count == 0) throw new Exception("No files found.");

                // unify columns
                Log("Unifying columns...");
                var allCols = allTables.SelectMany(t => t.Columns.Cast<DataColumn>().Select(c => c.ColumnName)).Distinct().ToList();
                foreach (var t in allTables)
                {
                    foreach (var col in allCols)
                        if (!t.Columns.Contains(col)) t.Columns.Add(col);
                }

                foreach (var t in allTables)
                    merged.Merge(t);

                Log($"Merged {merged.Rows.Count} total rows.");

                // basic computed column & filter example using NCalc
                if (cfg.ContainsKey("computed_columns"))
                {
                    var cc = cfg["computed_columns"] as Dictionary<object, object>;
                    if (cc != null && cc.ContainsKey("expressions"))
                    {
                        foreach (var expr in (cc["expressions"] as IEnumerable<object>) ?? Array.Empty<object>())
                        {
                            string e = expr.ToString() ?? "";
                            if (!e.Contains("=")) continue;
                            var parts = e.Split('='); if (parts.Length != 2) continue;
                            string newCol = parts[0].Trim(); string formula = parts[1].Trim();
                            if (!merged.Columns.Contains(newCol)) merged.Columns.Add(newCol);
                            foreach (DataRow r in merged.Rows)
                            {
                                var exprCalc = new Expression(formula);
                                foreach (DataColumn c in merged.Columns)
                                    exprCalc.Parameters[c.ColumnName] = r[c.ColumnName];
                                try { r[newCol] = exprCalc.Evaluate(); }
                                catch { r[newCol] = DBNull.Value; }
                            }
                        }
                    }
                }

                // Save result
                Log("Writing Excel output...");
                using (var wb = new XLWorkbook())
                {
                    var ws = wb.Worksheets.Add(merged, "Merged");
                    wb.SaveAs(outputFile);
                }

                Log($"✅ Done! Saved to {outputFile}");
            }
            catch (Exception ex)
            {
                Log("❌ " + ex.Message);
            }
            finally
            {
                btnRun.Enabled = true;
            }
        }
    }
}
